import { RenderOp } from "./RenderList";
import { AssetManager } from "../assets";

export const ProjectileDrawer = {
    draw(ctx: CanvasRenderingContext2D, op: RenderOp, globalTime: number) {
        const isRay = op.pSkillVis === 'BEAM'; 

        if (isRay && op.pTrail && op.pTrail.length > 0) {
            ctx.save();
            ctx.globalCompositeOperation = 'screen'; 

            const start = op.pTrail[op.pTrail.length - 1]; 
            const end = { x: op.pVisX, y: op.pVisY };

            ctx.shadowColor = op.pColor;
            ctx.shadowBlur = op.pIsUlt ? 25 : 15;
            ctx.strokeStyle = op.pColor;
            ctx.lineWidth = op.pIsUlt ? 20 : 10;
            ctx.globalAlpha = 0.4;
            ctx.beginPath();
            ctx.moveTo(start.x, start.y); ctx.lineTo(end.x, end.y);
            ctx.stroke();
            ctx.shadowBlur = 0;

            const grad = ctx.createLinearGradient(start.x, start.y, end.x, end.y);
            grad.addColorStop(0, 'rgba(255,255,255,0)');
            grad.addColorStop(0.2, op.pColor);
            grad.addColorStop(0.5, '#ffffff'); 
            grad.addColorStop(1, '#ffffff'); 

            ctx.strokeStyle = grad;
            ctx.lineWidth = op.pIsUlt ? 8 : 4;
            ctx.globalAlpha = 1.0;
            ctx.beginPath();
            ctx.moveTo(start.x, start.y); ctx.lineTo(end.x, end.y);
            ctx.stroke();

            ctx.translate(end.x, end.y);
            const pulse = 1.0 + Math.sin(globalTime * 25) * 0.3;
            const headSize = (op.pIsUlt ? 16 : 8) * pulse;
            ctx.shadowColor = '#fff';
            ctx.shadowBlur = 20;
            ctx.fillStyle = '#fff';
            ctx.beginPath(); ctx.arc(0, 0, headSize, 0, Math.PI*2); ctx.fill();

            ctx.restore();
            return;
        }

        if (op.pTrail && op.pTrail.length > 1) {
            ctx.save();
            ctx.globalCompositeOperation = 'screen';
            ctx.beginPath();
            const trail = op.pTrail;
            ctx.moveTo(trail[0].x, trail[0].y);
            for(let i=1; i<trail.length; i++) {
                const alpha = (i / trail.length) * 0.6;
                ctx.globalAlpha = alpha;
                ctx.lineTo(trail[i].x, trail[i].y);
            }

            ctx.strokeStyle = op.pColor;
            ctx.lineWidth = 5;
            ctx.lineJoin = 'round';
            ctx.lineCap = 'round';
            ctx.shadowColor = op.pColor;
            ctx.shadowBlur = 10;
            ctx.stroke();
            ctx.restore();
        }

        const shadowAltitude = op.pVisShadowY - op.pVisY; 
        if (Math.abs(shadowAltitude) > 5) {
            ctx.save();
            ctx.translate(Math.round(op.pVisX), Math.round(op.pVisShadowY));
            const shadowAlpha = Math.max(0, 0.3 - Math.abs(shadowAltitude)/1500);
            ctx.scale(1, 0.5); 
            ctx.fillStyle = `rgba(0,0,0,${shadowAlpha})`;
            ctx.beginPath(); ctx.arc(0, 0, 18, 0, Math.PI*2); ctx.fill();
            ctx.restore();
        }

        ctx.save();
        ctx.translate(Math.round(op.pVisX), Math.round(op.pVisY));
        if (op.pSpin !== 0) ctx.rotate(op.pSpin); 
        else ctx.rotate(op.pAngle);

        ctx.save();
        ctx.globalCompositeOperation = 'screen';
        ctx.globalAlpha = 0.5;
        ctx.fillStyle = op.pColor;
        ctx.beginPath();
        ctx.moveTo(35, 0); ctx.lineTo(-20, -25); ctx.lineTo(-5, 0); ctx.lineTo(-20, 25);
        ctx.fill();
        ctx.restore();

        const img = AssetManager.getProjectile(op.pSkillVis, op.pColor);
        if (img && img.width > 0) {
            const scale = op.pIsUlt ? 1.8 : 1.2;
            ctx.scale(scale, scale);
            ctx.drawImage(img, -48, -32, 96, 64);

            ctx.globalCompositeOperation = 'lighter';
            ctx.globalAlpha = 0.8;
            ctx.drawImage(img, -48, -32, 96, 64);
        }
        ctx.restore();
    }
};

import { GroundHazard } from "../../../../../types";
import { HEX_SIZE, ISO_SCALE_Y } from "../../../../../constants";
import { HAZARD_VISUALS } from "../../../../../data/vfx/hazard_visuals";
import { VFXFactory } from "../../../graphics/VFXFactory";
import { SurfacePainter } from "../../../graphics/painters/SurfacePainter";
import { VolumePainter } from "../../../graphics/painters/VolumePainter";

export const HazardPainter = {
    draw(ctx: CanvasRenderingContext2D, x: number, y: number, hazard: GroundHazard, globalTime: number) {
        const def = HAZARD_VISUALS[hazard.type] || HAZARD_VISUALS['GENERIC'];

        let fade = 1.0;
        if (hazard.duration < 0.8) fade = hazard.duration / 0.8;

        ctx.save();
        ctx.globalAlpha = fade;

        if (def.type === 'FOG') {
            const texture = VFXFactory.getTexture('SMOKE', def.primaryColor);
            const size = HEX_SIZE * 1.5;
            const speed = globalTime * def.speed;

            ctx.save();
            ctx.translate(x, y - 2); 
            ctx.scale(1, ISO_SCALE_Y);

            ctx.globalCompositeOperation = (hazard.type === 'POISON') ? 'screen' : 'lighter';

            ctx.save();
            ctx.rotate(speed * 0.12);
            ctx.globalAlpha = def.intensity * 0.8;
            ctx.drawImage(texture, -size/2, -size/2, size, size);
            ctx.restore();

            ctx.save();
            ctx.rotate(-speed * 0.08 + 1);
            ctx.scale(0.85, 0.85);
            ctx.globalAlpha = def.intensity * 0.5;
            ctx.drawImage(texture, -size/2, -size/2, size, size);
            ctx.restore();

            ctx.restore();
        }
        else if (def.type === 'LIQUID') {
            const speed = globalTime * def.speed;
            const intensity = def.intensity * (0.85 + Math.sin(speed * 0.8) * 0.15);
            SurfacePainter.drawLiquid(ctx, x, y, def.primaryColor, speed, intensity);
            if (def.cracks) SurfacePainter.drawCracks(ctx, x, y, def.secondaryColor, intensity * 0.8);
        }
        else if (def.type === 'CRYSTAL') {
            if (def.extrude) VolumePainter.drawExtrusion(ctx, x, y, HEX_SIZE * 0.8, 8, def.primaryColor, 0.7);

            ctx.save();
            ctx.translate(x, y);
            ctx.scale(1, ISO_SCALE_Y);
            const texture = VFXFactory.getTexture('ROCK', def.secondaryColor);
            ctx.globalCompositeOperation = 'screen';
            ctx.globalAlpha = 0.6;
            ctx.drawImage(texture, -15, -15, 30, 30);
            ctx.restore();
        }
        else if (def.type === 'VOID_HOLE') {
            ctx.save();
            ctx.translate(x, y);
            ctx.scale(1, ISO_SCALE_Y);
            ctx.fillStyle = '#000';
            ctx.globalAlpha = 0.95;
            ctx.beginPath(); ctx.arc(0, 0, HEX_SIZE * 0.65, 0, Math.PI*2); ctx.fill();

            const grad = ctx.createRadialGradient(0,0,HEX_SIZE*0.2, 0,0,HEX_SIZE * 0.8);
            grad.addColorStop(0, def.primaryColor);
            grad.addColorStop(1, 'transparent');
            ctx.fillStyle = grad;
            ctx.globalCompositeOperation = 'screen';
            ctx.globalAlpha = def.intensity;
            ctx.beginPath(); ctx.arc(0, 0, HEX_SIZE * 0.9, 0, Math.PI*2); ctx.fill();
            ctx.restore();
        }

        ctx.restore();
    }
};

import { HEX_SIZE, ISO_SCALE_Y } from "../../../constants";
import { VFXFactory } from "../VFXFactory";

export const SurfacePainter = {

    drawLiquid(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        color: string,
        time: number,
        intensity: number
    ) {
        ctx.save();
        ctx.translate(x, y);
        ctx.scale(1, ISO_SCALE_Y); 

        const r = HEX_SIZE * 0.95;

        ctx.beginPath();
        const segments = 12; 
        const twoPi = Math.PI * 2;

        for (let i = 0; i <= segments; i++) {
            const theta = (i / segments) * twoPi;
            const noise = Math.sin(theta * 2 + time) * 4 + Math.cos(theta * 3 - time * 0.5) * 2; 
            const px = Math.cos(theta) * (r + noise);
            const py = Math.sin(theta) * (r + noise);
            if (i === 0) ctx.moveTo(px, py);
            else ctx.lineTo(px, py);
        }
        ctx.closePath();

        ctx.fillStyle = color;
        ctx.globalAlpha = 0.85 * intensity;
        ctx.fill();

        ctx.globalCompositeOperation = 'multiply';
        ctx.beginPath();
        const rippleX = Math.sin(time * 0.5) * 6;
        const rippleY = Math.cos(time * 0.4) * 6;
        ctx.ellipse(rippleX, rippleY, r * 0.7, r * 0.6, time * 0.05, 0, twoPi);
        ctx.fill();

        ctx.globalCompositeOperation = 'overlay';
        ctx.fillStyle = '#fff';
        ctx.globalAlpha = 0.4;
        const bX = Math.cos(time * 1.2) * r * 0.5;
        const bY = Math.sin(time * 1.1) * r * 0.5;
        ctx.beginPath(); ctx.ellipse(bX, bY, 8, 4, 0, 0, twoPi); ctx.fill();

        ctx.restore();
    },

    drawFog(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        color: string,
        time: number
    ) {
        const texture = VFXFactory.getTexture('SMOKE_PUFF', color);
        const size = HEX_SIZE * 3.2;

        ctx.save();
        ctx.translate(x, y);
        ctx.scale(1, ISO_SCALE_Y);

        ctx.globalCompositeOperation = 'screen';
        ctx.globalAlpha = 0.12; 

        const puffs = 4;
        const twoPi = Math.PI * 2;

        for(let i=0; i<puffs; i++) {
            const angle = time * 0.15 + (i * twoPi / puffs);
            const dist = 15 + Math.sin(time * 0.8 + i) * 8;
            const px = Math.cos(angle) * dist;
            const py = Math.sin(angle) * dist;

            const pulse = 1.0 + Math.sin(time * 1.2 + i) * 0.15;
            const pSize = size * 0.55 * pulse;

            ctx.drawImage(texture, px - pSize/2, py - pSize/2, pSize, pSize);
        }

        ctx.globalAlpha = 0.18;
        ctx.drawImage(texture, -size/2, -size/2, size, size);

        ctx.restore();
    },

    drawCracks(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        color: string,
        intensity: number
    ) {
        const texture = VFXFactory.generateCracks(color);
        const size = HEX_SIZE * 2.4; 

        ctx.save();
        ctx.translate(x, y);
        ctx.scale(1, ISO_SCALE_Y); 

        ctx.globalCompositeOperation = 'lighter';
        ctx.globalAlpha = intensity;

        ctx.rotate((x * 0.001) + (y * 0.001)); 

        ctx.drawImage(texture, -size/2, -size/2, size, size);
        ctx.restore();
    },

    drawDetailTexture(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        type: string,
        color: string,
        seed: number
    ) {
        const variant = Math.abs(Math.floor(seed * 100));
        const texture = VFXFactory.getTerrainDetail(type, color, variant);
        const size = texture.width;

        ctx.drawImage(texture, x - size/2, y - size/2);
    }
};

import { Agent } from "../../../../game";
import { SpriteManager } from "../../../sprites";
import { UnitIndicatorPainter } from "./UnitIndicatorPainter";
import { UnitAuraPainter } from "./UnitAuraPainter";
import { VFXFactory } from "../../../graphics/VFXFactory";
import { UNIT_SCALE, ISO_SCALE_Y } from "../../../../../constants";

const HOVER_LIFT = 6; 

export const UnitShadowPainter = {
    draw(ctx: CanvasRenderingContext2D, agent: Agent, px: number, py: number, pz: number, t: number, isSilhouette: boolean) {
        if (isSilhouette || agent.visualStatus === 'POLYMORPH') return;

        const assets = SpriteManager.getUnitImages(agent.role, agent.team);
        const surfaceY = py;
        const tokenY = surfaceY - HOVER_LIFT;

        ctx.save();

        const jumpHeight = agent.physics.z;
        // 調低基礎透明度從 1.0 降至 0.35，避免呈現全黑塊
        const shadowScale = Math.max(0.4, 1.0 - (jumpHeight / 500));
        const shadowAlpha = Math.max(0.05, 0.35 - (jumpHeight / 300));
        const shadowBlob = VFXFactory.getTexture('SHADOW_BLOB', 'rgba(0,0,0,1)'); 

        ctx.save();
        ctx.translate(px, surfaceY); 
        ctx.scale(UNIT_SCALE, UNIT_SCALE); 
        ctx.scale(shadowScale, shadowScale);
        ctx.globalAlpha = shadowAlpha;
        ctx.globalCompositeOperation = 'multiply'; // 使用色彩增值模式讓陰影與地表融合

        const w = 110; // 稍微放寬陰影範圍增加柔和感
        const h = w * ISO_SCALE_Y;
        ctx.drawImage(shadowBlob, -w/2, -h/2, w, h); 
        ctx.restore();

        if (agent.hp > 0 && agent.castingSkillIdx !== -1) {
            const skill = agent.skills[agent.castingSkillIdx];
            if (skill && skill.tag === 'ULT') {
                UnitAuraPainter.drawUltimateChantVFX(ctx, agent, px, surfaceY, t);
            } else {
                UnitAuraPainter.drawCastingVFX(ctx, agent, px, surfaceY, t);
            }
        }

        ctx.save();
        ctx.translate(px, tokenY);
        ctx.scale(UNIT_SCALE, UNIT_SCALE); 
        ctx.drawImage(assets.base, -64, -64); 
        ctx.restore();

        if (agent.hp > 0) {
            ctx.save();
            ctx.translate(px, tokenY);
            ctx.scale(UNIT_SCALE, UNIT_SCALE); 

            const iconBaseY = -20; 
            ctx.translate(0, iconBaseY);
            const breath = Math.sin(t * 2) * 1.5;
            ctx.translate(0, breath);

            ctx.fillStyle = 'rgba(0,0,0,0.2)';
            ctx.beginPath(); ctx.ellipse(0, 28, 14, 6, 0, 0, Math.PI*2); ctx.fill();

            ctx.globalAlpha = 1.0; 
            ctx.shadowColor = 'rgba(0,0,0,0.3)'; ctx.shadowBlur = 5;
            ctx.drawImage(assets.icon, -32, -32, 64, 64);
            ctx.restore();
        }

        if (agent.castingSkillIdx !== -1) {
            const skill = agent.skills[agent.castingSkillIdx];
            if (skill) {
                const progress = 1 - (agent.castTimer / skill.cast);
                const radius = skill.aoeRadius || 1;
                const isAOE = skill.type === 'AOE';
                if (isAOE) {
                    ctx.save();
                    ctx.translate(px, surfaceY);
                    UnitIndicatorPainter.drawSkillGroundIndicator(ctx, 0, 0, skill.color, t, progress, radius, skill.tag, isAOE);
                    ctx.restore();
                }
            }
        }

        ctx.restore();
    }
};

