import { createCanvas } from "./CanvasUtils";
import { ParticlePainter } from "./painters/ParticlePainter";
import { ProjectilePainter } from "./painters/ProjectilePainter";
import { IconPainter } from "./painters/IconPainter";
import { HexGeometry } from "./utils/HexGeometry";
import { HEX_SIZE } from "../../constants";

const TEXTURE_SIZE = 128; 
const CENTER = TEXTURE_SIZE / 2;

export class VFXTextureCache {
    private cache: Map<string, HTMLCanvasElement> = new Map();

    public reset() { this.cache.clear(); }

    public getTexture(type: string, color: string): HTMLCanvasElement {
        if (['DUST', 'PEBBLE', 'CHIP', 'RUBBLE', 'DEBRIS', 'SHARD'].includes(type)) type = 'ROCK';
        if (['CLOUD', 'SMOKE_PUFF', 'MUSHROOM'].includes(type)) type = 'SMOKE';
        if (['GLOW', 'FLARE', 'CORE', 'ATMOSPHERE'].includes(type)) type = 'GLOW_SPRITE';

        const key = `T91_${type}_${color}`;
        if (this.cache.has(key)) return this.cache.get(key)!;

        const { canvas, ctx } = createCanvas(TEXTURE_SIZE, TEXTURE_SIZE);
        ctx.translate(CENTER, CENTER);
        const r = 40; 

        switch (type) {
            case 'SMOKE': ParticlePainter.drawSmoke(ctx, r, color); break;
            case 'GLOW_SPRITE': ParticlePainter.drawAtmosphere(ctx, r, color); break;
            case 'SPIKE':
            case 'SPARK': ParticlePainter.drawSpike(ctx, r * (type === 'SPARK' ? 0.3 : 0.8), color); break;
            case 'ROCK':
                ctx.fillStyle = color;
                HexGeometry.traceHex(ctx, 0, 0, r * 0.5, false);
                ctx.fill();
                break;
            case 'HEX_LOCK': IconPainter.drawHexLock(ctx, r, color); break;
            case 'SHADOW_BLOB':
                // 升級：使用層次漸變取代單色圓，解決黑色色塊問題
                const grad = ctx.createRadialGradient(0, 0, 0, 0, 0, r);
                grad.addColorStop(0, color); // 中心較深
                grad.addColorStop(0.6, 'rgba(0,0,0,0.3)');
                grad.addColorStop(1, 'transparent'); // 邊緣完全透明
                ctx.fillStyle = grad;
                ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI*2); ctx.fill();
                break;
            case 'CRACKS': ParticlePainter.drawCracks(ctx, r, color); break;
            case 'SLASH': ParticlePainter.drawSlash(ctx, r, color); break;
            default:
                ctx.fillStyle = '#ff00ff';
                ctx.fillRect(-5,-5,10,10);
                break;
        }

        this.cache.set(key, canvas);
        return canvas;
    }

    public generateGlowOrb(color: string): HTMLCanvasElement { return this.getTexture('GLOW_SPRITE', color); }
    public generateCracks(color: string): HTMLCanvasElement { return this.getTexture('CRACKS', color); }
    public generateFogCloud(color: string): HTMLCanvasElement {
        const key = `FOG_${color}`;
        if (this.cache.has(key)) return this.cache.get(key)!;
        const { canvas, ctx } = createCanvas(128, 64);
        const grad = ctx.createRadialGradient(64, 32, 0, 64, 32, 64);
        grad.addColorStop(0, color); grad.addColorStop(1, 'transparent');
        ctx.fillStyle = grad;
        ctx.beginPath(); ctx.ellipse(64, 32, 40, 25, 0, 0, Math.PI*2); ctx.fill();
        this.cache.set(key, canvas);
        return canvas;
    }

    public getTerrainDetail(type: string, color: string, variant: number): HTMLCanvasElement {
        const key = `DETAIL_${type}_${color}_${variant}`;
        if (this.cache.has(key)) return this.cache.get(key)!;

        const { canvas, ctx } = createCanvas(HEX_SIZE * 2, HEX_SIZE * 2);
        ctx.translate(HEX_SIZE, HEX_SIZE);

        ctx.fillStyle = color;
        ctx.globalAlpha = 0.3;

        if (type === 'FOREST') {
            ctx.beginPath();
            ctx.moveTo(0, -10);
            ctx.lineTo(8, 5);
            ctx.lineTo(-8, 5);
            ctx.closePath();
            ctx.fill();
        } else if (type === 'VOID') {
            ctx.beginPath();
            for(let i=0; i<4; i++) {
                const angle = i * Math.PI / 2;
                ctx.moveTo(0,0);
                ctx.lineTo(Math.cos(angle)*8, Math.sin(angle)*8);
            }
            ctx.strokeStyle = color;
            ctx.stroke();
        }

        this.cache.set(key, canvas);
        return canvas;
    }
}

export const VFXFactory = new VFXTextureCache();

import { ISO_SCALE_Y } from "../../../constants";
import { HexLayout } from "../../../types";

/**
 * 核心六邊形幾何真理 (Single Source of Truth) - V3.6 TA Corrected
 */
export const HexGeometry = {
    getVertices(radius: number, applyIso: boolean = true, layout: HexLayout = 'FLAT'): {x: number, y: number}[] {
        const vertices = [];
        const baseStartAngle = layout === 'FLAT' ? 0 : Math.PI / 6;
        const scaleY = applyIso ? ISO_SCALE_Y : 1.0;
        for (let i = 0; i < 6; i++) {
            const angle = baseStartAngle + i * Math.PI / 3;
            vertices.push({ 
                x: Math.cos(angle) * radius, 
                y: Math.sin(angle) * radius * scaleY 
            });
        }
        return vertices;
    },

    traceHex(ctx: CanvasRenderingContext2D, x: number, y: number, radius: number, applyIso: boolean = true, layout: HexLayout = 'FLAT') {
        const verts = this.getVertices(radius, applyIso, layout);
        ctx.beginPath();
        ctx.moveTo(x + verts[0].x, y + verts[0].y);
        for (let i = 1; i < 6; i++) {
            ctx.lineTo(x + verts[i].x, y + verts[i].y);
        }
        ctx.closePath();
    },

    /**
     * 向量旋轉繪製 - TA 修正版：確保先旋轉再投影
     */
    traceRotatedHex(ctx: CanvasRenderingContext2D, x: number, y: number, radius: number, rotation: number, applyIso: boolean = true, layout: HexLayout = 'FLAT') {
        // 1. 取得原始平面的頂點 (applyIso = false)
        const baseVerts = this.getVertices(radius, false, layout);
        const cosR = Math.cos(rotation);
        const sinR = Math.sin(rotation);
        const scaleY = applyIso ? ISO_SCALE_Y : 1.0;

        ctx.beginPath();
        for (let i = 0; i < 6; i++) {
            const vx = baseVerts[i].x;
            const vy = baseVerts[i].y;

            // 2. 進行二維旋轉矩陣運算
            const rx = vx * cosR - vy * sinR;
            const ry = vx * sinR + vy * cosR;

            // 3. 最後應用等角 Y 軸壓縮
            const px = x + rx;
            const py = y + ry * scaleY;

            if (i === 0) ctx.moveTo(px, py);
            else ctx.lineTo(px, py);
        }
        ctx.closePath();
    }
};

import { Particle } from "../../state";
import { ISO_SCALE_Y } from "../../../../../constants";
import { PROCEDURAL_VISUALS, PillarVisualDef } from "../../../../../data/vfx/procedural_visuals";
import { VolumePainter } from "../../../../graphics/painters/VolumePainter";
import { HexGeometry } from "../../../../graphics/utils/HexGeometry";
import { HexLayout } from "../../../../../types";

export const ProceduralPainter = {
    draw(ctx: CanvasRenderingContext2D, p: Particle, progress: number, now: number, layout: HexLayout = 'FLAT') {
        ctx.save();

        // 1. 處理地面法陣類 (Locked to Ground)
        if (['HEX_BEAM', 'GIANT_HEX', 'MAGIC_CIRCLE'].includes(p.type)) {
            // 使用 now * vRotation 確保動畫平滑，不跳幀
            const animRot = p.rotation + (p.vRotation ? p.vRotation * now : 0);

            if (p.type === 'GIANT_HEX') {
                this.drawGiantHex(ctx, p, animRot, layout);
            } else if (p.type === 'MAGIC_CIRCLE') {
                this.drawMagicCircle(ctx, p, animRot, layout);
            } else {
                this.drawStandardHexVfx(ctx, p, animRot, progress, layout);
            }
        }
        // 2. 處理體積投射類 (3D Entities)
        else if (p.type === 'PILLAR') {
            this.drawVolumetricPillar(ctx, p, progress, now);
        }
        else if (p.type === 'DOMAIN') {
            this.drawDomainField(ctx, p, progress, layout);
        }

        ctx.restore();
    },

    drawGiantHex(ctx: CanvasRenderingContext2D, p: Particle, rot: number, layout: HexLayout) {
        ctx.globalCompositeOperation = 'screen';

        // A. 擴散光環
        ctx.save();
        ctx.globalAlpha = 0.4 * (1 - p.life/p.maxLife);
        ctx.shadowColor = p.color;
        ctx.shadowBlur = 40;
        HexGeometry.traceRotatedHex(ctx, 0, 0, p.size * 1.2, rot * 0.5, true, layout);
        ctx.fillStyle = p.color;
        ctx.fill();
        ctx.restore();

        // B. 主幾何體 (高能核心)
        const grad = ctx.createRadialGradient(0,0,0, 0,0, p.size);
        grad.addColorStop(0, '#ffffff');
        grad.addColorStop(0.3, p.color);
        grad.addColorStop(1, 'transparent');

        ctx.fillStyle = grad;
        ctx.globalAlpha = 0.8;
        HexGeometry.traceRotatedHex(ctx, 0, 0, p.size, rot, true, layout);
        ctx.fill();

        // C. 邊緣外框 (銳利化)
        ctx.strokeStyle = '#ffffff';
        ctx.lineWidth = 3;
        ctx.globalAlpha = 1.0;
        HexGeometry.traceRotatedHex(ctx, 0, 0, p.size, rot, true, layout);
        ctx.stroke();
    },

    drawMagicCircle(ctx: CanvasRenderingContext2D, p: Particle, rot: number, layout: HexLayout) {
        ctx.globalCompositeOperation = 'screen';
        ctx.strokeStyle = p.color;
        ctx.lineWidth = 2;
        ctx.shadowColor = p.color;
        ctx.shadowBlur = 15;

        // 多層環繞幾何
        HexGeometry.traceRotatedHex(ctx, 0, 0, p.size, rot, true, layout);
        ctx.stroke();

        ctx.save();
        ctx.setLineDash([10, 5]);
        HexGeometry.traceRotatedHex(ctx, 0, 0, p.size * 0.85, -rot * 1.2, true, layout);
        ctx.stroke();
        ctx.restore();

        // 中心符文脈衝
        const pulse = 0.5 + Math.sin(rot * 2) * 0.2;
        ctx.globalAlpha = pulse;
        HexGeometry.traceRotatedHex(ctx, 0, 0, p.size * 0.4, rot * 3, true, layout);
        ctx.stroke();
    },

    drawStandardHexVfx(ctx: CanvasRenderingContext2D, p: Particle, rot: number, progress: number, layout: HexLayout) {
        ctx.globalCompositeOperation = 'screen';
        ctx.globalAlpha = (1 - progress) * 0.6;
        ctx.fillStyle = p.color;
        HexGeometry.traceRotatedHex(ctx, 0, 0, p.size, rot, true, layout);
        ctx.fill();
    },

    drawVolumetricPillar(ctx: CanvasRenderingContext2D, p: Particle, progress: number, now: number) {
        const h = p.height || 1000; 
        const w = p.size * (1 - progress * 0.5);
        const color = p.color;

        ctx.globalCompositeOperation = 'screen';

        // 核心漸變
        const grad = ctx.createLinearGradient(-w/2, 0, w/2, 0);
        grad.addColorStop(0, color); 
        grad.addColorStop(0.5, '#ffffff'); 
        grad.addColorStop(1, color); 

        ctx.fillStyle = grad;
        ctx.globalAlpha = (1 - progress) * 0.8;
        ctx.fillRect(-w/2, -h, w, h);

        // 掃描線動畫 (TA 增加)
        const scanY = -( (now * 500) % h );
        ctx.fillStyle = '#ffffff';
        ctx.globalAlpha = 0.3 * (1 - progress);
        ctx.fillRect(-w/2, scanY, w, 2);

        // 底部圓盤
        ctx.save();
        ctx.scale(1, ISO_SCALE_Y);
        const glow = ctx.createRadialGradient(0,0,0, 0,0, w * 2);
        glow.addColorStop(0, '#fff');
        glow.addColorStop(1, 'transparent');
        ctx.fillStyle = glow;
        ctx.globalAlpha = (1 - progress) * 0.5;
        ctx.beginPath(); ctx.arc(0, 0, w * 2, 0, Math.PI*2); ctx.fill();
        ctx.restore();
    },

    drawDomainField(ctx: CanvasRenderingContext2D, p: Particle, progress: number, layout: HexLayout) {
        const r = p.size;
        const h = 80;
        const opacity = 0.4 * (1 - progress);
        // 使用 3D 棱鏡繪製區域感
        VolumePainter.draw3DPrism(ctx, 0, 0, r, h, p.color, opacity, 'GRADIENT_FADE', layout);
    }
};

import { RenderOp } from "./RenderList";
import { AssetManager } from "../assets";

export const ProjectileDrawer = {
    draw(ctx: CanvasRenderingContext2D, op: RenderOp, globalTime: number) {
        const isRay = op.pSkillVis === 'BEAM'; 

        // 1. 光束類渲染 (Beams)
        if (isRay && op.pTrail && op.pTrail.length > 0) {
            ctx.save();
            ctx.globalCompositeOperation = 'screen'; 

            const start = op.pTrail[op.pTrail.length - 1]; 
            const end = { x: op.pVisX, y: op.pVisY };

            // 外層光暈
            ctx.shadowColor = op.pColor;
            ctx.shadowBlur = op.pIsUlt ? 30 : 15;
            ctx.strokeStyle = op.pColor;
            ctx.lineWidth = op.pIsUlt ? 16 : 8;
            ctx.globalAlpha = 0.4;
            ctx.beginPath(); ctx.moveTo(start.x, start.y); ctx.lineTo(end.x, end.y); ctx.stroke();

            // 內層核心 (純白)
            ctx.strokeStyle = '#ffffff';
            ctx.lineWidth = op.pIsUlt ? 6 : 3;
            ctx.globalAlpha = 1.0;
            ctx.beginPath(); ctx.moveTo(start.x, start.y); ctx.lineTo(end.x, end.y); ctx.stroke();

            // 頭部閃光
            ctx.translate(end.x, end.y);
            const pulse = 1.0 + Math.sin(globalTime * 30) * 0.2;
            ctx.fillStyle = '#fff';
            ctx.shadowBlur = 20;
            ctx.beginPath(); ctx.arc(0, 0, (op.pIsUlt ? 12 : 6) * pulse, 0, Math.PI*2); ctx.fill();

            ctx.restore();
            return;
        }

        // 2. 一般飛行物渲染 (Sprites + Trails)
        if (op.pTrail && op.pTrail.length > 1) {
            ctx.save();
            ctx.globalCompositeOperation = 'screen';
            ctx.beginPath();
            const trail = op.pTrail;
            ctx.moveTo(trail[0].x, trail[0].y);
            for(let i=1; i<trail.length; i++) {
                const alpha = (i / trail.length) * 0.5;
                ctx.globalAlpha = alpha;
                ctx.lineTo(trail[i].x, trail[i].y);
            }
            ctx.strokeStyle = op.pColor;
            ctx.lineWidth = 4;
            ctx.lineJoin = 'round';
            ctx.stroke();
            ctx.restore();
        }

        // 飛行物本體
        ctx.save();
        ctx.translate(Math.round(op.pVisX), Math.round(op.pVisY));
        if (op.pSpin !== 0) ctx.rotate(op.pSpin); 
        else ctx.rotate(op.pAngle);

        const img = AssetManager.getProjectile(op.pSkillVis, op.pColor);
        if (img && img.width > 0) {
            const scale = op.pIsUlt ? 1.8 : 1.2;
            ctx.scale(scale, scale);

            // 渲染兩次：一次色彩混合，一次發光
            ctx.globalAlpha = 1.0;
            ctx.drawImage(img, -48, -32, 96, 64);

            ctx.globalCompositeOperation = 'lighter';
            ctx.globalAlpha = 0.7;
            ctx.drawImage(img, -48, -32, 96, 64);
        }
        ctx.restore();
    }
};
